/* ==================== Gửi tin nhắn tới SillyTavern ====================
 * Chiến lược hạ cấp 3 tầng của homepage:
 *   1. sendUserMessage(msg)  —— hàm toàn cục do SillyTavern chèn vào (ưu tiên)
 *   2. DOM trực tiếp: tìm #send_textarea + #send_but của SillyTavern, set value + click (dự phòng)
 *   3. navigator.clipboard.writeText  —— sao chép vào clipboard (hạ cấp nữa)
 *   4. alert —— lời nhắc dự phòng cuối cùng
 * Trả về true nếu gửi thành công, false nếu chỉ hiển thị dự phòng
 */
function sendToTavern(msg){
  if(!msg||typeof msg!=='string')return false;

  /* ① Ưu tiên: hàm toàn cục do SillyTavern chèn vào */
  try{
    if(typeof sendUserMessage==='function'){sendUserMessage(msg);return true;}
  }catch(e){__dbg('sendToTavern.sendUserMessage.err',{msg:String(e).slice(0,120)});}

  /* ② DOM trực tiếp: thao tác textarea + nút gửi của trang SillyTavern */
  var tryDoc=function(doc){
    try{
      var inp=doc.querySelector('#send_textarea')||
              doc.querySelector('textarea[placeholder]:not(#playerInput)');
      var btn=doc.querySelector('#send_but')||
              doc.querySelector('#send_but_sheld')||
              doc.querySelector('button[title*="Send"]')||
              doc.querySelector('button[aria-label*="\u53d1\u9001"]:not(#castBtn)')||
              doc.querySelector('button[aria-label*="Gửi"]:not(#castBtn)')||
              doc.querySelector('button[aria-label*="Send"]');
      if(inp&&btn){
        inp.value=msg;
        inp.dispatchEvent(new Event('input',{bubbles:true}));
        inp.dispatchEvent(new Event('change',{bubbles:true}));
        setTimeout(function(){btn.click();},80);
        return true;
      }
    }catch(e){__dbg('sendToTavern.tryDoc.err',{msg:String(e).slice(0,120)});}
    return false;
  };
  try{
    if(tryDoc(document))return true;
    if(window.parent&&window.parent!==window){
      if(tryDoc(window.parent.document))return true;
    }
  }catch(e){__dbg('sendToTavern.parent.err',{msg:String(e).slice(0,120)});}

  /* ③ Hạ cấp: sao chép vào clipboard */
  try{
    if(navigator.clipboard&&navigator.clipboard.writeText){
      navigator.clipboard.writeText(msg).then(function(){
      showToast('Đã sao chép vào clipboard, hãy dán để gửi','ri-clipboard-fill');
      },function(){
        alert('Đã tạo lệnh cốt truyện (vui lòng tự dán vào SillyTavern):\n\n'+msg);
      });
      return true;
    }
  }catch(e){}
  alert('Đã tạo lệnh cốt truyện (vui lòng tự dán vào SillyTavern):\n\n'+msg);
  return false;
}

