function useItem(itemName,itemDesc){
  if(!itemName)return;
  /* Escape ký tự đặc biệt của HTML */
  function esc(s){return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');}
  var eName=esc(itemName);
  var eDesc=esc(itemDesc);
  /* Mã hóa dữ liệu vào thuộc tính data-* để nút dùng */
  var dataName=encodeURIComponent(itemName);
  var dataDesc=encodeURIComponent(itemDesc||'');

  var html='<div class="nearby-detail item-detail">'+
    '<div class="detail-avatar item-detail-avatar"><i class="ri-treasure-map-fill"></i></div>'+
    '<div class="detail-header">'+
      '<div class="detail-name">'+eName+'</div>'+
      '<div class="detail-close" onclick="closeItemDetail()"><i class="ri-close-line"></i></div>'+
    '</div>'+
    '<div class="detail-section">'+
      '<div class="detail-section-title"><i class="ri-information-fill"></i> Thông tin đạo cụ</div>'+
      '<div class="detail-row"><i class="ri-label-fill"></i><span class="detail-label">Tên</span><span class="detail-val">'+eName+'</span></div>'+
      (eDesc?'<div class="detail-row"><i class="ri-quill-pen-fill"></i><span class="detail-label">Chức năng</span><span class="detail-val">'+eDesc+'</span></div>':'')+
    '</div>'+
    '<div class="item-detail-actions">'+
      '<button class="item-use-btn" onclick="confirmUseItem(\''+dataName+'\',\''+dataDesc+'\')">'+
        '<i class="ri-check-fill"></i> Dùng đạo cụ này'+
      '</button>'+
    '</div>'+
    '<div class="item-detail-tip">Bấm “Dùng đạo cụ này” sẽ điền vào ô nhập phía dưới (không ghi đè nội dung có sẵn)</div>'+
  '</div>';

  var layer=document.getElementById('itemDetailLayer');
  if(!layer){
    layer=document.createElement('div');
    layer.id='itemDetailLayer';
    layer.className='nearby-detail-layer';
    document.body.appendChild(layer);
    /* Bấm vùng trống của layer để đóng popup; bấm vào nội dung bên trong thì không đóng */
    layer.addEventListener('click',function(e){
      if(e.target===layer)closeItemDetail();
    });
