/* Xác nhận dùng đạo cụ: nối vào ô nhập */
function confirmUseItem(encName,encDesc){
  var itemName=decodeURIComponent(encName||'');
  var itemDesc=decodeURIComponent(encDesc||'');
  if(!itemName)return;
  var parts=[itemName];
  if(itemDesc)parts.push(itemDesc);
  var text='Dùng đạo cụ · '+parts.join(' · ');
  closeItemDetail();
  if(typeof closePortal==='function')closePortal();
  if(playerInput){
    var cur=playerInput.value.trim();
    playerInput.value=cur?cur+'\n'+text:text;
    playerInput.focus();
    var len=playerInput.value.length;
    playerInput.setSelectionRange(len,len);
    autoResizeInput();
    showToast('Đã thêm đạo cụ: '+itemName.slice(0,18),'ri-treasure-map-fill');
  }
  return true;
}
window.confirmUseItem=confirmUseItem;

function sendInput(){
  const v=playerInput.value.trim();
  if(!v)return;
  var ok=sendToTavern(v);
  if(ok){
    showToast('Vận mệnh đã ghi lại lời thì thầm của bạn: '+v.slice(0,20)+(v.length>20?'…':''),'ri-magic-fill');
  }else{
    showToast('Lời thì thầm chưa được gửi (thông báo dự phòng)','ri-error-warning-line');
  }
  playerInput.value='';
  autoResizeInput();
}
castBtn.onclick=sendInput;
playerInput.addEventListener('keydown',function(e){
  if(e.key==='Enter'&&!e.shiftKey){
    e.preventDefault();
    sendInput();
  }
});

