function displayCgDomain(name){
  return CG_DOMAIN_LABEL[name]||name;
}

function displayCgCharName(name){
  return CG_CHAR_LABEL[name]||name;
}

function displayCgScene(name){
  return CG_SCENE_LABEL[name]||name;
}

function resolveCharAssetKey(name){
  var raw=String(name||'').trim().normalize('NFC');
  if(!raw)return '';
  if(CHAR_NAME_AV[raw])return raw;
  if(CHAR_ASSET_ALIAS[raw])return CHAR_ASSET_ALIAS[raw];
  if(CG_CHAR_LABEL[raw])return raw;
  if(CG_CHAR_LABEL[CHAR_ASSET_ALIAS[raw]])return CHAR_ASSET_ALIAS[raw];
  if(CG_CHAR_LABEL[raw])return raw;
  if(CG_CHAR_LABEL_TO_ASSET[raw])return CG_CHAR_LABEL_TO_ASSET[raw];
  var compact=raw.replace(/\s+/g,'');
  if(CHAR_ASSET_ALIAS[compact])return CHAR_ASSET_ALIAS[compact];
  if(CG_CHAR_LABEL_TO_ASSET[compact])return CG_CHAR_LABEL_TO_ASSET[compact];
  for(var key in CHAR_ASSET_ALIAS){
    if(key.replace(/\s+/g,'')===compact)return CHAR_ASSET_ALIAS[key];
  }
  for(var label in CG_CHAR_LABEL_TO_ASSET){
    if(label.replace(/\s+/g,'')===compact)return CG_CHAR_LABEL_TO_ASSET[label];
  }
  return raw;
}

function resolveCharAvatar(name){
  var key=resolveCharAssetKey(name);
  var label=displayCgCharName(key);
  return (typeof CHAR_NAME_AV!=='undefined' && (CHAR_NAME_AV[key]||CHAR_NAME_AV[label]))
    || (typeof charImgMap!=='undefined' && (charImgMap[key]||charImgMap[label]))
    || (typeof IMGS!=='undefined' && IMGS.av && (IMGS.av[key]||IMGS.av[label]))
    || '';
}

