/* ── Tương tác phòng trưng bày CG ── */
window.cgSetDomain=function(domain){
  cgGalleryState.domain=domain;
  try{localStorage.setItem('sjjy_cg_state',JSON.stringify(cgGalleryState));}catch(e){}
