/* Hộp chi tiết nhân vật */
window.cgOpenCharModal=function(char){
  char=resolveCharAssetKey(char);
  var overlay=document.getElementById('cgModalOverlay');
  if(!overlay)return;
  var cache=cgGetCache();
  var cat=cgGalleryState.category;
  var catData=cache[cat]||{};
  var unlockedScenes=catData[char]||[];
  var allScenes=Object.keys(CG_IMAGE_LISTS[cat]&&CG_IMAGE_LISTS[cat][char]||{});
  var done=unlockedScenes.filter(function(s){return allScenes.indexOf(s)>=0;}).length;
  var pct=allScenes.length?Math.floor(done/allScenes.length*100):0;

  /* Lấy độ hảo cảm từ dữ liệu ERA */
  var near=eraGet('Nhân vật gần đây')||{};
  var charData=near[char];
  if(!charData){
    /* Khớp mờ */
    var normC=char.normalize('NFC');
    for(var k in near){
      if(k.normalize('NFC')===normC||k.replace(/\s/g,'')===char.replace(/\s/g,'')){charData=near[k];break;}
  }
  }
  var favor=charData?Math.max(0,Math.min(100,Number(charData['Độ hảo cảm'])||0)):0;
  var favorMax=favor>=100;
  var allUnlocked=done>=allScenes.length&&allScenes.length>0;

  /* Nút mở khóa một lần */
  var unlockBtnHtml='';
  if(favorMax&&!allUnlocked){
    unlockBtnHtml='<button id="cg-unlock-all-btn" style="width:100%;margin-top:10px;padding:10px 16px;background:linear-gradient(135deg,var(--gold),var(--violet));border:none;border-radius:8px;color:#fff;font-size:13px;font-weight:bold;cursor:pointer;transition:all 0.2s;text-shadow:0 1px 2px rgba(0,0,0,0.3);box-shadow:0 2px 8px rgba(201,169,97,0.4);">'
      +'<i class="ri-lock-unlock-fill" style="margin-right:4px"></i>Độ hảo cảm đã đầy · Mở khóa toàn bộ CG (cần hảo cảm 100)</button>';
  }else if(allUnlocked){
    unlockBtnHtml='<div style="text-align:center;margin-top:10px;padding:8px;background:rgba(0,255,136,0.15);border-radius:8px;color:#00ff88;font-size:12px;font-weight:bold;">✓ Đã mở khóa toàn bộ CG</div>';
  }else{
    unlockBtnHtml='<div style="text-align:center;margin-top:10px;padding:8px;background:rgba(255,255,255,0.05);border-radius:8px;color:rgba(255,255,255,0.5);font-size:11px;">🔒 Hảo cảm '+favor+'/100 · Đạt 100 có thể mở khóa toàn bộ CG</div>';
  }

  /* Lưới 9 ô cảnh */
  var sceneHtml=allScenes.map(function(scene){
    var maxNum=cgGetMaxCount(cat,char,scene)||4;
