      return '<div class="cg-scene-cell" onclick="cgOpenFs(\''+cat+'\',\''+char.replace(/'/g,"\\'")+'\',\''+scene.replace(/'/g,"\\'")+'\','+maxNum+')" style="background:var(--abyss)">'+
        '<div class="cg-scene-thumb" data-cg-remote="'+url+'" style="background-image:url(\''+url+'\')" onerror="this.style.opacity=\'0.3\'"></div>'+
        '<div class="cg-scene-info"><div class="cg-scene-name">'+displayCgScene(scene)+'</div><div class="cg-scene-max">'+maxNum+'P</div></div>'+
        '</div>';
    }else{
      return '<div class="cg-scene-cell locked">'+
        '<div class="cg-scene-lock"><i class="ri-lock-line"></i></div>'+
        '<div class="cg-scene-info"><div class="cg-scene-name" style="color:var(--dim)">'+displayCgScene(scene)+'</div><div class="cg-scene-max">'+maxNum+'P</div></div>'+
        '</div>';
    }
