  if(typeof cgApplyImgCache==='function')setTimeout(function(){cgApplyImgCache(overlay);},50);
};

/* Mở khóa toàn bộ CG của nhân vật bằng một lần bấm (cần hảo cảm 100) */
function cgUnlockAllForChar(cat,char){
  var allScenes=CG_IMAGE_LISTS[cat]&&CG_IMAGE_LISTS[cat][char];
  if(!allScenes)return;
  var c=cgGetCache();
  if(!c[cat])c[cat]={};
  if(!c[cat][char])c[cat][char]=[];
  Object.keys(allScenes).forEach(function(scene){
    if(c[cat][char].indexOf(scene)<0){
      c[cat][char].push(scene);
    }
  });
  cgSaveCache(c);
  /* Làm mới popup */
  cgOpenCharModal(char);
  /* Làm mới giao diện chính của phòng trưng bày */
  if(typeof refreshPortal==='function')refreshPortal();
}
window.cgUnlockAllForChar=cgUnlockAllForChar;

window.cgCloseCharModal=function(){
  var overlay=document.getElementById('cgModalOverlay');
  if(overlay)overlay.classList.remove('active');
};

/* Trình xem toàn màn hình */
var cgFsState={cat:'',char:'',scene:'',index:1,max:1};
window.cgOpenFs=function(cat,char,scene,max){
  char=resolveCharAssetKey(char);
  scene=String(scene||'').trim();
  cgFsState={cat:cat,char:char,scene:scene,index:1,max:max};
  cgUpdateFsImg();
  document.getElementById('cgFsOverlay').classList.add('active');
};
window.cgCloseFs=function(){
  var overlay=document.getElementById('cgFsOverlay');
  if(overlay)overlay.classList.remove('active');
};
window.cgFsNav=function(dir){
  if(dir==='prev'){
    cgFsState.index=cgFsState.index>1?cgFsState.index-1:cgFsState.max;
  }else{
    cgFsState.index=cgFsState.index<cgFsState.max?cgFsState.index+1:1;
  }
  cgUpdateFsImg();
};
function cgUpdateFsImg(){
  var s=cgFsState;
  var url=CG_BASE_URL+encodeURIComponent(s.cat)+'/'+encodeURIComponent(s.char)+'/'+encodeURIComponent(s.scene)+s.index+'.webp';
  var img=document.getElementById('cgFsImg');
  if(!img)return;
  img.style.opacity='0.3';
  /* Ưu tiên cache: tra IndexedDB -> có thì dùng blobUrl -> không thì fetch + cache */
  cgLoadImg(url).then(function(displayUrl){
    img.onload=function(){img.style.opacity='1';};
    img.onerror=function(){img.style.opacity='1';};
    img.src=displayUrl;
  });
  document.getElementById('cgFsCharName').textContent=displayCgCharName(s.char);
  document.getElementById('cgFsSceneSub').textContent=displayCgScene(s.scene)+' · No.'+String(s.index).padStart(2,'0');
  document.getElementById('cgFsCtr').textContent=s.index+' / '+s.max;
  /* Điều hướng chấm tròn */
  var show=Math.min(s.max,14);
  var dh='';
  for(var i=1;i<=show;i++){
    dh+='<div class="cg-fs-dot'+(i===s.index?' cur':'')+'" onclick="cgFsGoto('+i+')"></div>';
  }
  document.getElementById('cgFsDots').innerHTML=dh;
}
window.cgFsGoto=function(i){
  cgFsState.index=i;
  cgUpdateFsImg();
};

/* ── Thay bất đồng bộ toàn bộ thumbnail data-cg-remote trong DOM bằng blobUrl cache ──
 * Quét mọi phần tử [data-cg-remote] trong vùng chứa,
 * với mỗi remoteUrl gọi cgLoadImg -> thay background-image
 */
function cgApplyImgCache(container){
  if(!container)container=document;
  var els=container.querySelectorAll('[data-cg-remote]');
  if(!els.length)return;
  els.forEach(function(el){
    var remoteUrl=el.getAttribute('data-cg-remote');
    if(!remoteUrl)return;
    el.removeAttribute('data-cg-remote'); /* Tránh xử lý lặp */
    cgLoadImg(remoteUrl).then(function(bUrl){
      if(bUrl&&bUrl!==remoteUrl){
        el.style.backgroundImage='url(\''+bUrl+'\')';
      }
    });
  });
}

/* ── Quản lý cache: hiển thị thống kê / xóa cache ── */
window.cgShowImgStats=function(){
  cgImgStats().then(function(st){
    var mb=(st.size/(1024*1024)).toFixed(1);
    var msg='Thống kê cache ảnh CG:\nĐã cache '+st.count+' ảnh\nDung lượng '+mb+' MB\nGiới hạn 200 MB';
    if(confirm(msg+'\n\nCó muốn xóa toàn bộ ảnh cache không?')){
      cgImgClear().then(function(ok){
        if(ok)showToast('Đã xóa cache CG','ri-delete-bin-fill');
        else showToast('Xóa thất bại','ri-error-warning-fill');
      });
    }
  });
};

