let currentPortal=null;
function openPortal(key){
  __dbg('OPEN_PORTAL_ENTER',{key:key});
  const d=portalData[key];
  if(!d){__dbg('OPEN_PORTAL_NO_DATA',{key:key});return;}
  currentPortal=d;
  currentTab=d.tabs[0];
  portalSigil.innerHTML='<i class="'+d.icon+'"></i>';
  portalTitle.textContent=d.title;
  portalEn.textContent=d.en;
  portalTabs.innerHTML=d.tabs.map(function(t){
    return '<button class="portal-tab'+(t===currentTab?' active':'')+'" data-tab="'+t+'">'+t+'</button>';
  }).join('');
  portalTabs.style.display=d.tabs.length<=1?'none':'';
  portalTabs.querySelectorAll('.portal-tab').forEach(function(btn){
      btn.onclick=function(){
      currentTab=btn.dataset.tab;
      portalTabs.querySelectorAll('.portal-tab').forEach(function(b){b.classList.toggle('active',b===btn)});
      portalBody.innerHTML=d.render(currentTab);
      portalBody.scrollTop=0;
      if(typeof cgApplyImgCache==='function')cgApplyImgCache(portalBody);
    };
  });
  __dbg('BEFORE_RENDER',{tab:currentTab});
  try{
    var __html=d.render(currentTab);
    __dbg('RENDER_OK',{htmlLen:__html?__html.length:0});
    portalBody.innerHTML=__html;
    portalBody.scrollTop=0;
    /* Sau khi DOM cập nhật thì thay thumbnail bằng blobUrl từ cache bất đồng bộ */
    if(typeof cgApplyImgCache==='function')setTimeout(function(){cgApplyImgCache(portalBody);},50);
  }catch(e){
    __dbg('RENDER_FAIL',{tab:currentTab,err:String(e),stack:e&&e.stack?String(e.stack):''});
    throw e;
  }
  portalOverlay.classList.add('active');
  __dbg('OPEN_PORTAL_DONE',{key:key});
  /* Đặt móc làm mới: khi dữ liệu ERA đổi thì render lại tab hiện tại */
  refreshPortal=function(){
    if(currentPortal&&portalOverlay.classList.contains('active')){
      portalBody.innerHTML=currentPortal.render(currentTab);
      portalBody.scrollTop=0;
      /* Sau khi DOM cập nhật thì thay thumbnail bằng blobUrl từ cache bất đồng bộ */
      if(typeof cgApplyImgCache==='function')cgApplyImgCache(portalBody);
    }
  };
}
