/* ════════ Lõi tích hợp ERA (bản điều khiển bằng data-era) ════════ */
/* Móc làm mới popup (do openPortal đặt) */
var currentTab=null;
var refreshPortal=function(){};

let currentStat = {};

// ==================== Hàm lọc lõi ====================
// Lọc $template (chuyển nguyên từ file trang trí thanh trạng thái Biên niên sử Vực Nứt)
function filterTemplates(obj) {
    if (!obj || typeof obj !== 'object') return obj;

    if (Array.isArray(obj)) return obj;

    const filtered = {};
    for (const key in obj) {
        if (key === '$template') continue;
        if (typeof obj[key] === 'object' && obj[key] !== null) {
            filtered[key] = filterTemplates(obj[key]);
        } else {
            filtered[key] = obj[key];
        }
    }
    return filtered;
}

// ==================== Hàm tiện ích ERA (điều khiển bằng data-era) ====================
// Hàm lấy giá trị chung (giải quyết đường dẫn data-era, lấy từ currentStat)
function eraGet(path, defaultVal = '') {
    if (!currentStat) return defaultVal;
    const parts = path.split('.');
    let val = currentStat;
    for (const p of parts) {
        if (val == null) return defaultVal;
        val = val[p];
    }
    return val !== undefined && val !== null ? val : defaultVal;
}

function eraGetDef(path, defaultVal) {
    return eraGet(path, defaultVal);
}

// Kiểm tra object có phải key mẫu hay không (bắt đầu bằng $)
function isTemplate(key){return key&&key.charAt(0)==='$'}

// Lấy dữ liệu thực bên dưới object (lọc $template)
function getItems(obj) {
    if (!obj || typeof obj !== 'object') return [];
    const clean = filterTemplates(obj);
    const items = [];
    for (const key in clean) {
        if (key === '$template') continue;
        items.push({ _key: key, ...clean[key] });
    }
    return items;
}

// ==================== Cập nhật mọi phần tử data-era ====================
function updateAllEraElements() {
    document.querySelectorAll('[data-era]').forEach(el => {
        const path = el.getAttribute('data-era');
        const value = eraGet(path, el.textContent || '');
        if (el.tagName === 'IMG') {
            if (value && typeof value === 'string' && value.startsWith('http')) el.src = value;
        } else {
            el.textContent = value;
        }
    });
}

