// ==================== Hàm render chính (bản điều khiển bằng data-era) ====================
function renderAll(stat) {
    if (!stat) return;
    currentStat = filterTemplates(stat);   // Dữ liệu toàn cục đã lọc template

    updateAllEraElements();                // Điểm chính: cập nhật mọi data-era
    updateNearbyCharacter();               // Cập nhật thanh thoại dưới cùng (nhân vật gần đây · suy nghĩ nội tâm)
    renderSpiritPanel();                   // Cập nhật bảng nhân vật gần đây bên phải (độ hảo cảm / chỉ số điều giáo)
    renderQuestList();                     // Vẽ cuộn nhiệm vụ nhánh bên trái
    renderChapterConditions();             // Vẽ điều kiện tiến triển chương bên trái
    renderWorldChapter();                  // Vẽ đại thế giới hiện tại · chương cốt truyện bên trái
    renderBroadcast();                     // Cập nhật băng thông báo động

    // Phòng trưng bày CG: quét lịch sử chat để tự thu nhận minh họa mới
    cgScanChat();

    // Tùy chọn: làm mới bảng cổng sao đang mở
    if (typeof refreshPortal === 'function') refreshPortal();

    // Cập nhật MK trên thanh trạng thái
    const mkEl = document.getElementById('current-mk');
    if (mkEl) mkEl.textContent = `MK: ${stat.$meta?.mk || '——'}`;
    const midEl = document.getElementById('current-message-id');
    if (midEl) midEl.textContent = `Mã tin nhắn: ${stat.$meta?.message_id || '——'}`;
    const luEl = document.getElementById('last-update');
    if (luEl) luEl.innerHTML = `Cập nhật lần cuối <span class="font-mono">${new Date().toLocaleTimeString('zh-CN')}</span>`;
}

// ==================== Bên trái: cuộn nhiệm vụ nhánh ====================
function renderQuestList(){
  var cont=document.getElementById('questList');
  if(!cont)return;
  var side=eraGet('Hệ thống nhánh cốt truyện')||{};
  var items=getItems(side);
  if(!items.length){
    cont.innerHTML='<div class="quest-card" style="opacity:.5"><div class="quest-body"><div class="quest-name" style="color:var(--dim)">Chưa có nhiệm vụ nhánh</div></div></div>';
    return;
  }
  var html='';
  items.forEach(function(it){
    var desc=it['Mô tả nhánh cốt truyện']||'Câu chuyện nhánh chờ khám phá';
    var days=it['Số ngày đếm ngược'];
    days=(days!=null&&days!=='')?('Còn lại '+days+' ngày'):'';
    var reward=it['Phần thưởng ủy thác']||'';
    var name=it._key||'Nhiệm vụ nhánh';
    html+=
      '<div class="quest-card" style="padding:5px 10px;">'+
        '<div class="quest-avatar" style="width:24px;height:24px;font-size:11px;flex-shrink:0;"><i class="ri-route-fill"></i></div>'+
        '<div class="quest-body" style="min-width:0;">'+
          '<div class="quest-head">'+
            '<span class="quest-tag" style="font-size:9px;">Nhánh</span>'+
            '<span class="quest-name" style="font-size:11px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;flex:1;min-width:0;">'+name+'</span>'+
            (days?'<span class="quest-priority" style="font-size:9px;flex-shrink:0;">'+days+'</span>':'')+
          '</div>'+
        '</div>'+
      '</div>';
  });
  cont.innerHTML=html;
}

// ==================== Bên trái: điều kiện tiến triển chương ====================
function renderChapterConditions(){
  var cont=document.getElementById('chapterConditions');
  if(!cont)return;
  var ch=eraGet('Điều kiện tiến triển chương')||{};
  var html='';
  for(var i=1;i<=5;i++){
    var text=ch['Điều_kiện_'+i]||ch['Điều kiện '+i]||'Cần bổ sung';
    var done=ch['Điều_kiện_'+i+'_hoàn_thành']===true;
    var icon=done?'ri-check-fill':'ri-radiobox-line';
    var status=done?'Đã hoàn thành':'Chưa hoàn thành';
    html+=
      '<div class="cond-card'+(done?' done':'')+'">'+
        '<div class="cond-icon"><i class="'+icon+'"></i></div>'+
        '<div class="cond-text">'+text+'</div>'+
        '<div class="cond-status">'+status+'</div>'+
      '</div>';
  }
  if(!html)html='<div class="cond-card" style="opacity:.5"><div class="cond-icon"><i class="ri-question-line"></i></div><div class="cond-text" style="color:var(--dim)">Chưa có điều kiện chương</div><div class="cond-status">——</div></div>';

  /* Nhiệm vụ nhánh (một dòng gọn) */
  var side=eraGet('Hệ thống nhánh cốt truyện')||{};
  var sideItems=getItems(side);
  if(sideItems.length){
    html+='<div class="panel-title" style="margin-top:12px"><i class="ri-route-fill"></i>Nhiệm vụ nhánh</div>';
    sideItems.forEach(function(it){
      var days=it['Số ngày đếm ngược'];
      var daysStr=(days!=null&&days!=='')?'Còn lại '+days+' ngày':'Chờ khám phá';
      var name=it._key||'Nhiệm vụ nhánh';
      html+=
        '<div class="cond-card">'+
          '<div class="cond-icon"><i class="ri-flag-line"></i></div>'+
          '<div class="cond-text" style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">'+name+'</div>'+
          '<div class="cond-status" style="font-size:9px;">'+daysStr+'</div>'+
        '</div>';
    });
  }

  cont.innerHTML=html;
}

// ==================== Bên trái: đại thế giới hiện tại · chương cốt truyện ====================
function renderWorldChapter(){
  var nameEl=document.getElementById('currentWorldName');
  var chEl=document.getElementById('currentChapterName');
  if(!nameEl&&!chEl)return;
  var worlds=eraGet('Hệ thống đại thế giới')||{};
  var worldName='——';
  var chapter='——';
  for(var k in worlds){
    if(worlds[k]&&worlds[k]['Thế giới hiện tại đang ở']===true){
      worldName=k;
      chapter=worlds[k]['Chương cốt truyện']||'——';
      break;
    }
  }
  if(nameEl)nameEl.textContent=worldName;
  if(chEl)chEl.textContent=chapter;
}

// ==================== Băng thông báo động ====================
function renderBroadcast(){
  var el=document.getElementById('broadcastText');
  if(!el)return;
  var parts=[];

  /* ① Thông báo tài nguyên truyền thông */
  var media=eraGet('Hệ thống truyền thông')||{};
  var mediaKeys=Object.keys(media);
  if(mediaKeys.length){
    var mediaMsgs=mediaKeys.map(function(k){
      var v=media[k];
      if(typeof v==='string'&&/^https?:\/\//.test(v)){
        return '【Truyền thông】'+k+'（'+(/\.(png|jpg|jpeg|gif|webp|bmp)$/i.test(v)?'ảnh':'liên kết')+'）';
      }
      return '【Truyền thông】'+k+'：'+(v==null?'——':String(v).slice(0,30));
    });
    parts.push(mediaMsgs.join(' ◆ '));
  }else{
    parts.push('【Truyền thông】Chưa có tài nguyên truyền thông');
  }

  /* ② Thông báo nhiệm vụ nhánh */
  var side=eraGet('Hệ thống nhánh cốt truyện')||{};
  var sideItems=getItems(side);
  if(sideItems.length){
    var sideMsgs=sideItems.map(function(it){
      var name=it._key||'Nhánh';
      var desc=(it['Mô tả nhánh cốt truyện']||'Chờ khám phá').slice(0,40);
      var days=it['Số ngày đếm ngược'];
      return '【Nhánh】'+name+' · '+desc+(days!=null&&days!==''?' · Còn lại '+days+' ngày':'');
    });
    parts.push(sideMsgs.join(' ◆ '));
  }else{
    parts.push('【Nhánh】Chưa có nhiệm vụ nhánh');
  }

  /* Gộp nội dung thông báo, dùng khoảng trắng toàn giác để tách */
  var content=parts.join('　　');
  el.textContent=content;

  /* Tốc độ rất chậm: nền 120 giây, nội dung càng dài càng chậm */
  var len=content.length;
  var duration=Math.max(60,Math.round(len/2));
  el.style.animationDuration=duration+'s';
}

