    nearbyDetailRow('Độ hảo cảm',ch['Độ hảo cảm'],'ri-heart-fill'),
    nearbyDetailRow('Đánh giá thực lực',ch['Đánh giá thực lực'],'ri-sword-fill'),
    nearbyDetailRow('Trinh nữ',ch['Trinh nữ'],'ri-flower-fill'),
    nearbyDetailRow('Đã thành lợn nái',ch['Đã thành lợn nái'],'ri-piggy-bank-fill'),
    nearbyDetailRow('Chỉ số điều giáo',ch['Chỉ số điều giáo'],'ri-sparkling-fill'),
    nearbyDetailRow('Trang phục hiện tại',ch['Trang phục hiện tại'],'ri-shirt-fill'),
