    layer.id='nearbyDetailLayer';
    layer.className='nearby-detail-layer';
    document.body.appendChild(layer);
    /* Bấm vùng trống (chính layer) để đóng hộp thoại, bấm nội dung bên trong thì không đóng */
    layer.addEventListener('click',function(e){
      if(e.target===layer)closeNearbyDetail();
