// ==================== Thanh thoại dưới cùng (luân chuyển nhân vật gần đây · suy nghĩ nội tâm) ====================
var __nearbyItems = [];      // Toàn bộ danh sách nhân vật gần đây hiện tại
var __nearbyRotateItems = []; // Danh sách nhân vật thực sự tham gia luân chuyển (4 nhân vật vừa thay đổi gần nhất)
var __nearbyIdx = 0;         // Chỉ số luân chuyển hiện tại
var __nearbyTimer = null;    // Bộ định thời luân chuyển
var __NEARBY_INTERVAL = 5000; // Khoảng cách luân chuyển 5 giây
var __NEARBY_ROTATE_COUNT = 4; // Số nhân vật luân chuyển

/* Theo dõi thay đổi suy nghĩ nội tâm */
var __prevThoughts = {};        // Tên nhân vật -> văn bản suy nghĩ nội tâm lần trước
var __recentChangedQueue = [];  // Hàng đợi tên nhân vật vừa thay đổi (mới nhất phía trước, khử trùng lặp)

// Render nhân vật gần đây theo chỉ số chỉ định lên thanh thoại
function renderNearbyAt(idx) {
    if (!__nearbyRotateItems.length) return;
    if (idx >= __nearbyRotateItems.length) idx = 0;
    __nearbyIdx = idx;
    const ch = __nearbyRotateItems[idx];

    const nameEl = document.getElementById('speakerName');
    const roleEl = document.querySelector('[data-era-nearby="role"]');
    const thoughtEl = document.getElementById('dialogText');
    if (nameEl) nameEl.textContent = displayCgCharName(ch._key) || ch._key || 'Nhân vật gần đây';
    if (roleEl) {
        const roleParts = [
            ch['Đánh giá thực lực'],
            ch['Trinh nữ'] === false ? 'Đã mất trinh' : (ch['Trinh nữ'] === true ? 'Trinh nữ' : ''),
            ch['Đã thành lợn nái'] === true ? 'Lợn nái' : '',
            ch['Chỉ số điều giáo'] != null && ch['Chỉ số điều giáo'] !== 0 ? 'Điều giáo ' + ch['Chỉ số điều giáo'] : '',
            ch['Độ hảo cảm'] != null ? 'Hảo cảm ' + ch['Độ hảo cảm'] : ''
        ].filter(Boolean);
        roleEl.textContent = roleParts.join(' · ') || '——';
    }
    if (thoughtEl) {
        const thought = ch['Suy nghĩ nội tâm'] || '……';
        thoughtEl.innerHTML = thought + '<span class="cursor"></span>';
    }

    // Ảnh đại diện
    const glyph = document.getElementById('speakerGlyph');
    if (glyph) {
        const img = resolveCharAvatar(ch._key);
        if (img) {
            glyph.classList.add('has-img');
            glyph.innerHTML = '';
            const imgEl = document.createElement('img');
            imgEl.src = img;
            imgEl.alt = displayCgCharName(ch._key) || ch._key || 'Nhân vật gần đây';
            imgEl.onerror = function(){
                this.style.display = 'none';
                this.parentNode.classList.remove('has-img');
                this.parentNode.innerHTML = '<i class="ri-user-3-fill"></i>';
            };
            glyph.appendChild(imgEl);
        } else {
            glyph.classList.remove('has-img');
            glyph.innerHTML = '<i class="ri-user-3-fill"></i>';
        }
    }
}

function startNearbyCarousel() {
    if (__nearbyTimer) { clearInterval(__nearbyTimer); __nearbyTimer = null; }
    if (!__nearbyRotateItems.length) return;
    __nearbyIdx = 0;
    renderNearbyAt(__nearbyIdx);
    if (__nearbyRotateItems.length > 1) {
        __nearbyTimer = setInterval(function(){
            __nearbyIdx = (__nearbyIdx + 1) % __nearbyRotateItems.length;
            renderNearbyAt(__nearbyIdx);
        }, __NEARBY_INTERVAL);
    }
}

// Gọi khi dữ liệu ERA cập nhật: làm mới danh sách nhân vật gần đây và luân chuyển các suy nghĩ nội tâm vừa thay đổi
function updateNearbyCharacter() {
    const near = eraGet('Nhân vật gần đây') || {};
    __nearbyItems = getItems(near);
    const nameEl = document.getElementById('speakerName');
    const roleEl = document.querySelector('[data-era-nearby="role"]');
    const thoughtEl = document.getElementById('dialogText');

    if (!__nearbyItems.length) {
        if (__nearbyTimer) { clearInterval(__nearbyTimer); __nearbyTimer = null; }
        if (nameEl) nameEl.textContent = 'Nhân vật gần đây';
        if (roleEl) roleEl.textContent = '——';
        if (thoughtEl) thoughtEl.innerHTML = 'Chưa có suy nghĩ nội tâm của nhân vật gần đây.<span class="cursor"></span>';
        __nearbyRotateItems = [];
        /* Không xóa __prevThoughts, giữ lịch sử để lần sau tránh nhận nhầm toàn bộ là "mới" */
        return;
    }

    /* ① Kiểm tra thay đổi suy nghĩ nội tâm (đã có ghi nhận, văn bản khác nhau và suy nghĩ mới không rỗng -> thay đổi thật) */
    var changedItems = [];
    __nearbyItems.forEach(function(ch){
        var name = ch._key || '';
        var thought = ch['Suy nghĩ nội tâm'] || '';
        var prev = __prevThoughts[name];
        /* Chỉ khi suy nghĩ mới không rỗng và khác lần trước mới tính là thay đổi */
        if(prev !== undefined && thought && prev !== thought){
            changedItems.push(ch);
        }
        __prevThoughts[name] = thought;
    });

    /* ② Có thay đổi -> chỉ luân chuyển các nhân vật đã thay đổi */
    if(changedItems.length > 0){
        __nearbyRotateItems = changedItems;
        startNearbyCarousel();
        return;
    }

    /* ③ Không thay đổi -> khởi tạo lần đầu (chỉ gồm nhân vật có suy nghĩ nội tâm), sau đó giữ nguyên vòng quay cũ */
    if(__nearbyRotateItems.length === 0){
        __nearbyRotateItems = __nearbyItems.filter(function(ch){
            return ch['Suy nghĩ nội tâm'] && ch['Suy nghĩ nội tâm'].trim();
        });
        if(!__nearbyRotateItems.length){
            __nearbyRotateItems = __nearbyItems.slice();
        }
        startNearbyCarousel();
    }
    /* Nếu không thì giữ vòng quay hiện có, không khởi động lại */
}

// Gọi API
function requestCurrentVars() {
    eventEmit('era:getCurrentVars');
}

function forceSync() {
    eventEmit('era:forceSync', { mode: 'latest' });
}

// ==================== Lắng nghe ERA ====================
function setupERAListeners() {
    // Bảo đảm eventOn / eventEmit tồn tại (môi trường trợ lý quán rượu)
    if (typeof eventOn === 'undefined') {
        console.warn("⚠️ eventOn chưa được định nghĩa, hãy xác nhận đang chạy trong môi trường trợ lý quán rượu");
        return;
    }

    eventOn('era:writeDone', (detail) => {
        console.log('%c[ERA] writeDone', 'color:#67e8f9', detail);
        if (detail.statWithoutMeta) {
            renderAll(detail.statWithoutMeta);
        }
        /* Phòng trưng bày CG: sau khi ERA ghi xong thì quét lịch sử chat để mở CG mới */
        setTimeout(function(){cgScanChat();},300);
    });

    eventOn('era:queryResult', (detail) => {
        if (detail.result && detail.result.error) {
            console.error('ERA truy vấn thất bại:', detail.result.error);
            return;
        }
        if (detail.queryType === 'getCurrentVars' && detail.result) {
            renderAll(detail.result.statWithoutMeta || detail.result.stat);
        }
    });

    // Khởi tạo và lấy dữ liệu một lần
    setTimeout(() => {
        if (typeof eventEmit === 'function') {
            eventEmit('era:getCurrentVars');
        }
    }, 1200);
}

// ==================== Khởi tạo ====================
window.onload = function() {
    setupERAListeners();
    /* Phòng trưng bày CG: quét khởi tạo + quét định kỳ lịch sử chat */
    setTimeout(function(){cgScanChat();},2000);
    setInterval(function(){cgScanChat();},15000);
    /* Phòng trưng bày CG: MutationObserver theo dõi tin nhắn mới theo thời gian thực (tham chiếu cơ chế thanh trạng thái loveli) */
    (function(){
      var __cgObserver=new MutationObserver(function(mutations){
        var changed=false;
        mutations.forEach(function(mut){
          mut.addedNodes.forEach(function(node){
            if(node.nodeType!==1&&node.nodeType!==3)return;
            var txt=node.textContent||node.nodeValue||'';
            if(!txt)return;
            /* Lọc nhanh: chỉ kích hoạt quét với node chứa <img> hoặc đường dẫn SFW/NSFW */
            if(txt.indexOf('<img>')>=0||txt.indexOf('SFW/')>=0||txt.indexOf('NSFW/')>=0||txt.indexOf('&lt;img&gt;')>=0){
              changed=true;
            }
          });
        });
        if(changed)setTimeout(function(){cgScanChat();},200);
      });
      __cgObserver.observe(document.body,{childList:true,subtree:true});
      /* Đồng thời theo dõi tài liệu cha (giao diện chính của quán rượu) */
      try{
        if(window.parent&&window.parent.document&&window.parent.document!==document){
          __cgObserver.observe(window.parent.document.body,{childList:true,subtree:true});
        }
      }catch(e){}
    })();
    document.addEventListener('keydown',function(e){
      if(e.key==='Escape'){
        var fs=document.getElementById('cgFsOverlay');
        var modal=document.getElementById('cgModalOverlay');
        if(fs&&fs.classList.contains('active')){cgCloseFs();return;}
        if(modal&&modal.classList.contains('active')){cgCloseCharModal();return;}
      }
    });
    /* Bấm nền hộp thoại CG để đóng */
    var __cgModal=document.getElementById('cgModalOverlay');
    if(__cgModal)__cgModal.addEventListener('click',function(e){if(e.target===__cgModal)cgCloseCharModal();});
    var __cgFs=document.getElementById('cgFsOverlay');
    if(__cgFs)__cgFs.addEventListener('click',function(e){if(e.target===__cgFs)cgCloseFs();});
    /* Khởi động vòng quay video lập họa trung tâm */
    startSpiritVideoRotation();
    console.log("%c🌌 Kỷ nguyên Sự Giới · La bàn tinh giới + lắng nghe ERA đã tải", "color:#F4C842; font-weight:bold; font-size:14px");
};
</script>

